<template><div><div class="ui-form-grid"><FormItem label="证件类型" required><Select :value="value.type||''" :disabled="disabled" @on-change="set('type',$event)"><Option v-for="(label,key) in types" :key="key" :value="key">{{label}}</Option></Select></FormItem><FormItem label="证件姓名" required><Input :value="value.name" maxlength="100" :disabled="disabled" @input="set('name',$event)"/></FormItem><FormItem label="证件号码" required><Input :value="value.number" maxlength="32" :disabled="disabled" :placeholder="protectedValues[prefix+'.number']?'已有受保护值，留空保留':'填写完整证件号码'" @input="set('number',$event)"/><p v-if="protectedValues[prefix+'.number']" class="ui-meta">已保存：{{protectedValues[prefix+'.number']}}</p></FormItem><FormItem label="证件地址"><Input :value="value.address" maxlength="512" :disabled="disabled" :placeholder="protectedValues[prefix+'.address']?'已有受保护地址，留空保留':''" @input="set('address',$event)"/></FormItem><FormItem label="有效期开始" required><DatePicker type="date" format="yyyy-MM-dd" :value="value.validFrom||''" :disabled="disabled" @on-change="set('validFrom',$event)"/></FormItem><FormItem label="长期有效"><Checkbox :value="!!value.longTerm" :disabled="disabled" @on-change="set('longTerm',$event)">长期有效</Checkbox></FormItem><FormItem v-if="!value.longTerm" label="有效期截止" required><DatePicker type="date" format="yyyy-MM-dd" :value="value.validThrough||''" :disabled="disabled" @on-change="set('validThrough',$event)"/></FormItem></div><AttachmentList :value="value.frontFileId" purpose="CHANNEL" :scope="scope+':front'" title="证件正面" editable images-only :disabled="disabled" @input="set('frontFileId',$event)"/><AttachmentList v-if="value.type!=='OVERSEA_PASSPORT'" :value="value.backFileId" purpose="CHANNEL" :scope="scope+':back'" title="证件反面" editable images-only :disabled="disabled" @input="set('backFileId',$event)"/></div></template>
<script>import accessible from '../accessibility';import AttachmentList from './AttachmentList';export default {mixins:[accessible],components:{AttachmentList},props:{value:{type:Object,required:true},scope:{type:String,required:true},prefix:{type:String,required:true},protectedValues:{type:Object,default:()=>({})},disabled:Boolean},data:()=>({types:{MAINLAND_IDCARD:'大陆身份证',OVERSEA_PASSPORT:'护照',HONGKONG:'香港通行证',MACAO:'澳门通行证',TAIWAN:'台湾居民通行证',FOREIGN_RESIDENT:'外国人永久居留证',HONGKONG_MACAO_RESIDENT:'港澳居民居住证',TAIWAN_RESIDENT:'台湾居民居住证'}}),methods:{set(key,value){const next={...this.value,[key]:value};if(key==='longTerm'&&value)next.validThrough=null;this.$emit('input',next);}}};</script>
